#!/bin/zsh
# Charrette de l'intro avec les passagers ASSIS DEDANS (24/11/2026, reprise de la saison 1) : avant, les passagers étaient des sprites
# posés derrière une charrette vide et semblaient debout derrière elle. Ici, une seule image FLUX par vue, passagers compris, puis
# une vidéo LTX par vue pour le cycle de pas (tools/intro_cart.py). Étapes, chacune validée sur planche avant la suivante :
#   1. cart3 : profil vers la droite, trois passagers (le héros endormi à l'arrière, le Nordique blond, le voleur) ;
#   2. cart2 : la même image sans le héros (après qu'il a été éjecté dans la rue) ;
#   3. rear2 : de trois-quarts arrière, s'éloignant vers le haut à droite (montée vers le pont), deux passagers.
# FLUX 3 Klein local, gratuit, relançable (saute ce qui existe). Sorties : work/intro/cart2/.
cd "$(dirname "$0")/../work/intro" || exit 1; mkdir -p cart2
SP="full body game sprite, hand-painted 1990s PC point-and-click adventure game art, sarcastic cartoon style with realistic adult proportions, detailed painterly shading, bold dark outlines, saturated warm colors, plain flat solid magenta background, no shadow, no text"
g(){ out="cart2/$1"; seed="$2"; shift 2; [ -f "$out" ] || flux-image "$@" -o "$out" --seed $seed >/dev/null 2>&1; echo "ok $out"; }
step="${1:-1}"
if [ "$step" = 1 ]; then for s in 1 2 3 4; do
  g cart3_$s.png $((1200+s)) "Exactly the same horse-drawn wooden prisoner cart as the first reference image, same brown horse in harness, same grumpy old coachman in a fur hat and brown cloak on the front bench holding the reins, same low plank side rails and two big spoked wooden wheels, seen exactly from the side, pure profile, moving to the right. Three prisoners now sit INSIDE the cart bed, seated low on the floor of the cart between its side rails: the near side rail hides them below the chest, only their shoulders and heads rise above it. At the back of the cart sits the viking of the fourth reference (horned iron helmet, blond ponytail, fur collar), slumped against the back of the cart, fast asleep with his eyes closed and his head tilted on his shoulder. In the middle sits the burly blond braided Nord of the second reference, turned toward the sleeping viking. At the front, just behind the coachman, sits the bald scrawny thief of the third reference, hunched and nervous. Their wrists are tied with rope. They are clearly inside the cart, never behind it. The whole horse and cart are visible with a margin all around. $SP" -i cart_side_301.png -i comp_32.png -i thief_42.png -i ref_hero.png -s 1344x768
done; fi
if [ "$step" = 2 ]; then for s in 1 2 3 4; do   # cart3_4 validée par Stéphan le 24/11
  g cart2_$s.png $((1210+s)) "Exactly the same image as the reference: same cart, same horse, same coachman, same blond braided Nord and same bald thief seated at the same places inside the cart, same pose, same size, same style and colors, same magenta background. Only one change: the sleeping viking with the horned helmet at the back of the cart is gone, his place at the back of the cart bed is now empty, we see the inside of the back corner of the cart." -i cart3_4.png -s 1344x768
  g rear2_$s.png $((1220+s)) "The same horse-drawn prisoner cart as the reference image, same brown horse in harness, same grumpy coachman in a fur hat and brown cloak on the front bench, same blond braided Nord and same bald thief seated inside the cart bed, and no viking. Now seen in a three-quarter rear view, from behind and from the left, driving away from the viewer toward the upper right corner of the picture: we see the back of the cart with its tailgate, its left side receding in perspective, both rear wheels and the left front wheel, the backs and heads of the two prisoners, the back of the coachman and his fur hat, and ahead of them the horse's hindquarters, tail and back, walking away to the upper right. The whole horse and cart are visible with a margin all around. $SP" -i cart3_4.png -s 1344x768
done; fi

# 4. cycles de pas (LTX, local) depuis les images validées : vidéo 4 s sur fond magenta, caméra qui suit (la charrette reste en place),
#    puis tools/intro_cart.py --src=… --out=cart3|cart2|rear2 (rear2 avec --xy).
if [ "$step" = 4 ]; then
  L(){ out="cart2/$1.mp4"; img="$2"; act="$3"; seed="$4"; [ -f "$out" ] || video-locale "CAMERA: locked-off tracking shot that follows the cart at exactly its speed, so the horse and cart stay at the same place and the same size in the frame for the whole shot. SUBJECT: $act ENV: plain flat solid magenta background, perfectly uniform, no ground, no shadow, no scenery." -o "$out" -d 4 -s 1344x768 -i "$img" --seed $seed -- --no-audio >/dev/null 2>&1; echo "ok $out"; }
  SIDE="the horse-drawn prisoner cart in pure side profile moving to the right. ACTION: the horse walks at a steady regular walk, its four legs moving in a natural walking gait, its head nodding with each step, the spoked cart wheels turning, the coachman and the seated prisoners swaying gently with the bumps of the road."
  [ -n "$C3" ] && L ltx_cart3 "cart2/$C3" "$SIDE The viking at the back stays fast asleep, his head nodding." 41
  [ -n "$C2" ] && L ltx_cart2 "cart2/$C2" "$SIDE" 42
  # 24/11 : la vue de dos sans image de fin partait sur 489 px (la charrette s'éloignait) ; RLOOP=1 : même image au début et à la fin
  [ -n "$RLOOP" ] && { o=cart2/ltx_rear2_loop.mp4; [ -f $o ] || video-locale "CAMERA: locked-off tracking shot that follows the cart at exactly its speed, so the horse and cart stay at the same place and the same size in the frame for the whole shot. SUBJECT: the horse-drawn prisoner cart seen in three-quarter rear view, driving away toward the upper right. ACTION: the horse walks at a steady regular walk, its hind legs and tail moving in a natural walking gait, the cart wheels turning, the coachman and the two seated prisoners swaying gently with the bumps. The cart keeps exactly the same viewing angle and size for the whole shot. ENV: plain flat solid magenta background, perfectly uniform, no ground, no shadow, no scenery." -o $o -d 2.5 -s 1344x768 -i cart2/$R2 -i cart2/$R2 --seed 143 -- --no-audio >/dev/null 2>&1; echo "ok $o"; }
  [ -n "$R2" ] && L ltx_rear2 "cart2/$R2" "the horse-drawn prisoner cart seen in three-quarter rear view, driving away toward the upper right. ACTION: the horse walks at a steady regular walk away from us, its hind legs and tail moving in a natural walking gait, the cart wheels turning, the coachman and the two seated prisoners swaying gently with the bumps." 43
fi
echo fini
